package dominoes

// Domino represents a single domino tile. The two elements hold the number
// of dots on each half of the stone. A tile may be flipped, so [1,2] and
// [2,1] are equivalent.
type Domino [2]int

// MakeChain reports whether the given dominoes can be arranged into a chain
// in which the dots on adjacent halves match, and the dots on the two ends
// of the chain (the first and last stone) match each other.
//
// If such a chain exists, it is returned: every input domino is used exactly
// once, possibly flipped. Otherwise ok is false.
func MakeChain(input []Domino) ([]Domino, bool) {
	n := len(input)
	if n == 0 {
		return []Domino{}, true
	}

	// Treat the dominoes as the edges of a multigraph whose vertices are the
	// dot values. A valid closed chain is an Eulerian circuit of that graph,
	// which exists if and only if every vertex has even degree and all
	// vertices with non-zero degree lie in a single connected component.
	adj := make(map[int][]int, 2*n) // vertex -> incident edge IDs
	for i, d := range input {
		adj[d[0]] = append(adj[d[0]], i)
		adj[d[1]] = append(adj[d[1]], i)
	}
	for _, eids := range adj {
		if len(eids)%2 != 0 {
			return nil, false
		}
	}

	start := 0
	for v := range adj {
		start = v
		break
	}
	seen := make(map[int]bool, len(adj))
	stack := []int{start}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if seen[v] {
			continue
		}
		seen[v] = true
		for _, id := range adj[v] {
			if w := otherEnd(input[id], v); !seen[w] {
				stack = append(stack, w)
			}
		}
	}
	if len(seen) != len(adj) {
		// The dominoes split into disconnected groups (for example two
		// separate loops), so no single closed chain can use all of them.
		return nil, false
	}

	// Hierholzer's algorithm traces the circuit in linear time.
	pos := make(map[int]int, len(adj))
	used := make([]bool, n)
	var circuit []int
	stack = []int{start}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		for pos[v] < len(adj[v]) && used[adj[v][pos[v]]] {
			pos[v]++
		}
		if pos[v] < len(adj[v]) {
			id := adj[v][pos[v]]
			pos[v]++
			used[id] = true
			stack = append(stack, otherEnd(input[id], v))
		} else {
			circuit = append(circuit, v)
			stack = stack[:len(stack)-1]
		}
	}
	if len(circuit) != n+1 {
		// Unreachable given the checks above; guard just in case.
		return nil, false
	}

	chain := make([]Domino, n)
	for i := 0; i < n; i++ {
		chain[i] = Domino{circuit[i], circuit[i+1]}
	}
	return chain, true
}

// otherEnd returns the endpoint of the domino that is not v.
func otherEnd(d Domino, v int) int {
	if d[0] == v {
		return d[1]
	}
	return d[0]
}

